function credit(){return `${pageHeader('A QUICK CREDIT HEALTH CHECK','Credit score','Understand what’s shaping your score and keep an eye on changes.',`<span class="tag">Sample snapshot · 18 Sep</span>`)}<div class="page-grid"><section class="feature-panel"><div class="eyebrow" style="text-align:center">CIBIL SCORE</div><div class="score-ring"><div class="score-inner"><strong>782</strong><span>Very good</span></div></div><p style="text-align:center">Up 12 points since your previous check</p></section><section class="feature-panel"><h3>What’s working well</h3><div class="item-list" style="margin-top:12px"><div class="list-row"><div class="grow"><strong>On-time payments</strong><small>No missed payments in 12 months</small></div><span class="positive">Strong</span></div><div class="list-row"><div class="grow"><strong>Credit utilisation</strong><small>Using 24% of available limit</small></div><span class="positive">Healthy</span></div><div class="list-row"><div class="grow"><strong>Credit history</strong><small>Longest account: 6 years</small></div><span class="muted">Good</span></div></div></section><section class="feature-panel wide"><div class="split"><div><h3>Keep your profile healthy</h3><p>Pay bills on time and avoid applying for several new credit lines at once.</p></div><button class="btn" data-toast="Score update reminder set for next month">Remind me next month</button></div><p style="margin-top:14px;font-size:10px">Score shown is mock data for this prototype and is not a credit bureau result.</p></section></div>`}
function loans(){return `${pageHeader('BORROW WITH THE WHOLE PICTURE','Loans','See your current commitments and compare repayment scenarios.') }<div class="page-grid"><section class="feature-panel"><div class="eyebrow">TOTAL OUTSTANDING</div><div class="metric-large">${money(allLiabilitiesTotal())}</div><p>Across ${2+state.trackedAssets.filter(a=>a.loanBalance>0).length} active commitments</p><div class="item-list" style="margin-top:16px"><div class="list-row"><div class="circle-logo">⌂</div><div class="grow"><strong>Home loan · HDFC</strong><small>₹3,80,000 remaining · EMI ₹18,500</small></div><span class="tag">9.1% p.a.</span></div><div class="list-row"><div class="circle-logo">▤</div><div class="grow"><strong>Credit card · HDFC</strong><small>₹55,500 statement balance · due 5 Oct</small></div><span class="tag amber">Due soon</span></div></div></section><section class="feature-panel"><h3>Try a repayment scenario</h3><p>Estimate how an extra payment could affect a sample loan.</p><div class="field" style="margin:17px 0"><label for="extraPay">Extra monthly payment</label><input id="extraPay" type="number" placeholder="₹ 5,000" /></div><button class="btn primary" id="loanCalc">See estimate</button><div id="loanResult" style="margin-top:12px"></div></section><section class="feature-panel wide"><h3>Before taking on new debt</h3><p>Look at the total cost, fees, repayment flexibility and how a new EMI fits alongside your savings goal and other commitments.</p></section></div>`}
function goals(){return `${pageHeader('MAKE ROOM FOR WHAT’S COMING','Goals & events','Plan for the moments you care about, without losing sight of today.',`<button class="btn primary" id="newGoal">＋ Add a goal</button>`)}<div class="page-grid"><section class="feature-panel wide"><div class="split"><div><h3>Diwali celebration</h3><p>Due 8 November · Personal event</p></div><span class="tag amber">44 days to go</span></div><div class="split" style="margin:19px 0 8px"><span class="panel-sub">₹8,000 saved of ₹20,000</span><strong style="font-size:12px">40%</strong></div><div class="progress"><span style="width:40%"></span></div><div class="split" style="margin-top:17px"><span class="muted" style="font-size:11px">Suggested reserve: ₹12,000 more</span><button class="btn small" data-toast="Event reserve updated">Set aside money</button></div></section><section class="feature-panel"><div class="split"><div><h3>Japan trip</h3><p>Travel · June 2027</p></div><span class="tag">On track</span></div><div class="metric-large">₹1.2L</div><p>₹1.2L of ₹2.5L saved · 48%</p><div class="progress" style="margin-top:12px"><span style="width:48%"></span></div><div class="trip-encouragement"><strong>You’re making room for something meaningful.</strong><span>Travel can be part of a thoughtful money plan. Keep the trip budget comfortable alongside bills and your safety buffer.</span></div></section><section class="feature-panel"><div class="split"><div><h3>Emergency fund</h3><p>Safety net · Ongoing</p></div><span class="tag">On track</span></div><div class="metric-large">4.2 <span class="muted" style="font:400 12px 'DM Sans'">months</span></div><p>Of your 6-month comfort target</p><div class="progress" style="margin-top:12px"><span style="width:70%"></span></div></section>${state.confirmedActions.length?`<section class="feature-panel wide"><h3>Reminders you added</h3><div class="item-list">${state.confirmedActions.map(note=>`<div class="list-row"><div class="circle-logo">◷</div><div class="grow"><strong>${escapeHtml(note)}</strong><small>Added locally in this demo · no account changes</small></div><span class="tag">Saved</span></div>`).join('')}</div></section>`:''}<section class="feature-panel wide"><div class="eyebrow">WHAT’S ON YOUR RADAR</div><div class="item-list"><div class="list-row"><div class="circle-logo">◷</div><div class="grow"><strong>HDFC card payment</strong><small>₹55,500 · due 5 October</small></div><span class="tag amber">10 days</span></div><div class="list-row"><div class="circle-logo">✧</div><div class="grow"><strong>Reward points expiry</strong><small>1,850 points · HDFC Regalia Gold</small></div><span class="tag amber">36 days</span></div></div></section></div>`}
const providers=[['Groww','Mutual funds · Stocks','G','green'],['Zerodha','Stocks · Mutual funds','Z',''],['INDmoney','US stocks · Funds','I',''],['Sahamati / Account Aggregator','Banks · Loans · Deposits','S','green'],['HDFC Bank','Bank account · Credit card','H',''],['ICICI Bank','Bank account · Credit card','IC','']];
function accounts(){return `${pageHeader('YOUR MONEY, CONNECTED WITH CONSENT','Connected accounts','Choose what to connect. You can review or revoke access at any time.',`<span class="tag">${providers.length} sample providers</span>`)}<section class="feature-panel wide" style="margin-bottom:16px"><div class="split"><div><h3>One clear view, with your permission</h3><p>Banking data is represented through mocked integrations. A production connector would request specific consent and show its scope and duration.</p></div><span class="secure-dot"></span></div></section><div class="page-grid">${providers.map(p=>`<section class="feature-panel"><div class="split"><div class="split" style="justify-content:flex-start"><div class="circle-logo">${p[2]}</div><div><h3>${p[0]}</h3><p>${p[1]}</p></div></div><span class="tag ${p[3]}">${p[0]==='HDFC Bank'?'Connected':'Available'}</span></div><div class="split" style="margin-top:17px"><span class="panel-sub">${p[0]==='HDFC Bank'?'Last synced today':'Mock integration'}</span><button class="btn small ${p[0]==='HDFC Bank'?'':'soft'}" data-connect="${p[0]}">${p[0]==='HDFC Bank'?'Manage':'Connect'}</button></div></section>`).join('')}</div><section class="feature-panel wide" style="margin-top:16px"><h3>Your consent controls</h3><p>See which data is shared, why it’s needed and when access ends. Connections in this demo do not access real accounts.</p><button class="btn" style="margin-top:14px" data-toast="Consent dashboard opened">Review data permissions&nbsp; →</button></section>`}
function profile(){return `${pageHeader('YOUR SPACE','Profile & settings','Make OptiSpend feel a little more like yours.') }<div class="page-grid"><section class="feature-panel"><div class="split" style="justify-content:flex-start"><div class="avatar" style="width:48px;height:48px;display:grid;place-items:center;font-size:17px">A</div><div><h3>Ananya Rao</h3><p>ananya.rao@example.com</p></div></div><div class="item-list" style="margin-top:15px"><div class="list-row"><div class="grow"><strong>Life stage</strong><small>${state.segment==='student'?'College student':state.segment==='early'?'Early career':'Established / high earning'}</small></div><button class="text-link" id="editSegment">Change&nbsp; →</button></div><div class="list-row"><div class="grow"><strong>Home location</strong><small>Hyderabad, Telangana</small></div><button class="text-link" id="locationEdit">Edit&nbsp; →</button></div></div></section><section class="feature-panel"><h3>Preferences</h3><div class="item-list"><label class="list-row" style="cursor:pointer"><div class="grow"><strong>Upcoming money reminders</strong><small>Events, bills and expiring rewards</small></div><input type="checkbox" checked></label><label class="list-row" style="cursor:pointer"><div class="grow"><strong>Local opportunities</strong><small>Relevant ideas for Hyderabad</small></div><input type="checkbox" checked></label><label class="list-row" style="cursor:pointer"><div class="grow"><strong>Weekly money summary</strong><small>A quiet check-in every Sunday</small></div><input type="checkbox"></label></div></section><section class="feature-panel wide"><h3>Privacy & security</h3><p>Choose what you share, review active connections and remove access when you like. Account security settings would live here in a connected product.</p><button class="btn" style="margin-top:15px" data-go="accounts">Manage connected accounts</button></section></div>`}
function assetTitle(){return state.segment==='student'?"What's up with your assets?":state.segment==='established'?'Know your asset value':'Current asset status'}
function assetPulse(){const total=state.trackedAssets.reduce((sum,a)=>sum+a.value,0);return `${pageHeader('ASSET PULSE',assetTitle(),state.segment==='student'?'See what your things might be worth today, with the guesswork clearly labeled.':state.segment==='established'?'A considered view of estimated values, depreciation and holdings-specific updates.':'Track estimated resale values and understand how they change over time.',`<button class="btn primary" id="addAsset">＋ Add an asset</button>`)}<section class="asset-hero"><div><div class="eyebrow">ESTIMATED VALUE OF TRACKED ASSETS</div><div class="asset-total">${state.hideBalance?'••••••':money(total)}</div><p>Across ${state.trackedAssets.length} items · sample estimates, not live quotes</p></div><div class="asset-hero-note"><span>◒</span><div><strong>More context, less pressure</strong><small>Resale value is one part of a decision. The value an item brings to your life matters too.</small></div></div></section><div class="asset-layout"><section class="feature-panel"><div class="split"><div><h3>Things you own</h3><p>Estimates vary by exact model, condition, location and seller.</p></div><span class="tag">${state.trackedAssets.length} tracked</span></div><div class="item-list" style="margin-top:14px">${state.trackedAssets.map(a=>{const loss=a.value-a.purchasePrice,retained=Math.max(0,Math.min(100,Math.round(a.value/a.purchasePrice*100)));return `<div class="asset-row"><div class="asset-kind-icon">${a.kind==='Car'?'⌑':a.kind==='Property'?'⌂':a.kind==='Phone'?'▣':a.kind==='Watch'?'◷':'◇'}</div><div class="asset-row-info"><div class="asset-title-line"><strong>${escapeHtml(a.name)}</strong><span class="tag ${loss>=0?'':'amber'}">${a.kind}</span></div><div class="asset-meta">Bought ${escapeHtml(a.purchased)} · ${escapeHtml(a.source)}${a.loanBalance?` · ${money(a.loanBalance)} loan remaining`:``}</div><div class="asset-retention"><div class="progress"><span style="width:${retained}%;background:${loss>=0?'#77a77b':'#d6a27f'}"></span></div><small>${retained}% of purchase price</small></div></div><div class="asset-current"><strong>${state.hideBalance?'••••':money(a.value)}</strong><small>${loss>=0?'↑ '+money(loss):'↓ '+money(Math.abs(loss))} since purchase</small></div><button class="text-link asset-detail" data-asset-id="${a.id}">Details&nbsp; →</button></div>`}).join('')}</div></section><section class="feature-panel asset-chart-panel"><div class="eyebrow">A SIMPLE DEPRECIATION EXAMPLE</div><h3>Value changes over time</h3><p>Illustrative curve for a typical car—not a quote for your specific model.</p><svg class="asset-chart" viewBox="0 0 360 120" role="img" aria-label="Illustrative car value trend from purchase through year five"><defs><linearGradient id="assetFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#76a77a" stop-opacity=".24"/><stop offset="1" stop-color="#76a77a" stop-opacity="0"/></linearGradient></defs><path d="M28 18 C72 34 91 43 126 53 S195 70 223 79 S289 96 334 103 L334 112 L28 112 Z" fill="url(#assetFill)"/><path d="M28 18 C72 34 91 43 126 53 S195 70 223 79 S289 96 334 103" fill="none" stroke="#578962" stroke-width="3" stroke-linecap="round"/><circle cx="28" cy="18" r="4" fill="#578962"/><circle cx="334" cy="103" r="4" fill="#578962"/><path d="M28 112H334" stroke="#e7ebe5"/><text x="28" y="119">Purchase</text><text x="309" y="119">Year 5</text></svg><div class="asset-chart-note"><span>Depreciating assets are modeled with a broad category range.</span><button class="text-link" id="depreciationInfo">How estimates work&nbsp; →</button></div><div class="valuation-sources"><div><strong>Cars</strong><small>Cars24 · Spinny · CarWale</small></div><div><strong>Phones & gadgets</strong><small>Cashify · resale marketplace</small></div><div><strong>Property</strong><small>Local comparable sales & manual updates</small></div></div><span class="demo-label">PROVIDER PRICES ARE NOT CONNECTED IN THIS DEMO</span></section></div><div class="section-head"><h2>Updates tied to what you own</h2><button class="text-link" data-go="invest">Your holdings&nbsp; →</button></div><section class="feature-panel owned-news"><div class="owned-news-mark">↗</div><div class="owned-news-copy"><div class="split"><strong>Tata Motors · sample portfolio holding</strong><span class="tag">Owned holding</span></div><p>Example company update card to show how your feed can stay focused on investments you hold. Live company news and market signals are not connected.</p><small>When connected, each update will show its source, time and matched holding—without pushing a buy-or-sell call.</small></div></section><div class="asset-emotion"><span>✦</span><p>You’ve been making thoughtful plans. A trip, a car, a new phone—money is here to support the life you want. Use these estimates as context, not a scorecard for what you’re allowed to enjoy.</p><button class="text-link" data-go="goals">Revisit your Japan goal&nbsp; →</button></div>`}
function chat(){const messages=state.chatMessages.map((m,i)=>`<article class="chat-message ${m.role==='user'?'from-user':'from-agent'}"><div class="chat-avatar">${m.role==='user'?'A':'✳'}</div><div class="chat-message-body"><div class="chat-speaker">${m.role==='user'?'You':'Opti · your money guide'}</div><div class="chat-bubble">${escapeHtml(m.text).replace(/\n/g,'<br>')}</div>${m.route?`<button class="btn small" data-chat-route="${m.route}" data-prefill-name="${escapeHtml(m.prefillName||'')}" data-prefill-amount="${escapeHtml(m.prefillAmount||'')}">${m.routeLabel||'Open this view'}&nbsp; →</button>`:''}${m.confirm?`<button class="btn small primary" data-chat-confirm="${i}">Review and confirm&nbsp; →</button>`:''}</div></article>`).join('');return `${pageHeader('A CLEARER WAY TO MANAGE MONEY','Talk to your money','Ask a question, compare a choice, or make a plan.')}<section class="chat-shell"><div class="chat-topline"><div><span class="assistant-orb">✳</span><strong>Opti</strong><span class="chat-online"><i></i> Ready</span></div><span class="demo-label">SAMPLE DATA · DEMO ASSISTANT</span></div><div class="chat-log" id="chatLog" aria-live="polite">${messages}${state.chatLoading?'<article class="chat-message from-agent"><div class="chat-avatar">✳</div><div class="chat-message-body"><div class="chat-speaker">Opti · your money guide</div><div class="chat-bubble typing"><i></i><i></i><i></i></div></div></article>':''}</div>${state.chatMessages.length===1?`<div class="chat-suggestions"><div class="suggestion-heading">TRY ASKING</div><button class="suggestion" data-chat-prompt="Can I afford a ₹20,000 purchase this month?">Can I afford a purchase this month? <span>↗</span></button><button class="suggestion" data-chat-prompt="How am I doing on my Japan trip goal?">How is my Japan trip goal going? <span>↗</span></button><button class="suggestion" data-chat-prompt="Which card should I use for movie tickets?">Which card should I use for movie tickets? <span>↗</span></button><button class="suggestion" data-chat-prompt="What needs my attention this week?">What needs my attention this week? <span>↗</span></button><button class="suggestion" data-chat-prompt="What might my car be worth now?">What might my car be worth now? <span>↗</span></button></div>`:''}<form class="chat-composer" id="chatForm"><label class="sr-only" for="chatInput">Ask Opti a money question</label><input id="chatInput" autocomplete="off" placeholder="Ask anything about your money…" ${state.chatLoading?'disabled':''}/><button class="send-chat" type="submit" aria-label="Send message" ${state.chatLoading?'disabled':''}>↑</button></form><div class="chat-disclaimer">Opti uses mock data in this prototype. It can prepare plans for review, but can’t access accounts, browse live offers or move money.</div></section>`}
function agentReply(question){const q=question.toLowerCase();if(/net worth|assets|liabilit|balance|how much.*have/.test(q))return {text:`Your sample net worth is ${money(netWorthTotal())}: ${money(allAssetsTotal())} in assets minus ${money(allLiabilitiesTotal())} in liabilities. You have about ${money(84620)} available after the bills and savings goal currently in this demo. These are illustrative numbers, not live account data.`,route:'divers',routeLabel:'Explore assets'};if(/japan|trip|travel|holiday|vacation/.test(q)){if(/remind|reminder|set/.test(q))return {text:'I can add a local reminder to review lounge eligibility before your Japan trip. This won’t contact an issuer or change any account. Would you like to add that demo reminder?',confirm:'Review lounge reminder'};return {text:`Your sample Japan goal is ${money(120000)} of ${money(250000)} saved, leaving ${money(130000)}. Nearly half is already there—that steady progress is worth celebrating. Travel can be a meaningful goal; plan a version that keeps bills and your comfort buffer covered. For the HDFC Millennia card, the current sample terms tie a domestic lounge voucher to spending ₹1 lakh in a calendar quarter, and you choose it instead of a ₹1,000 voucher. Check eligibility, participating lounges and current terms before relying on it.`,route:'goals',routeLabel:'Open goals & trip plan'}}if(/credit score|cibil/.test(q))return {text:'Your sample CIBIL score is 782, marked “Very good,” up 12 points from the previous sample snapshot. This is mock data, not a bureau check.',route:'credit',routeLabel:'View credit score'};if(/movie|cinema|bookmyshow/.test(q))return {text:'For BookMyShow, the sample HDFC Millennia offer estimates 5% cashback on eligible non-EMI spends, subject to its remaining cycle cap. The example Axis movie offer may give up to ₹200 off at selected cinemas, subject to booking and spend terms. Compare the final checkout price; I can’t confirm which saves more without the live offer terms.',route:'rewards',routeLabel:'Compare card benefits'};if(/reward|cashback|cashpoint|benefit|lounge|card/.test(q))return {text:'Your sample profile includes HDFC Millennia, Axis Bank and HDFC Regalia Gold. Millennia has sample 5% cashback at listed partner merchants and 1% on other eligible spend, each subject to caps and exclusions. I can show the full terms or compare a specific purchase. No offers are live-connected.',route:'rewards',routeLabel:'Open rewards'};if(/spend|buy|purchase|afford|price|cost|ticket|laptop|phone|product/.test(q)){const amt=q.match(/(?:₹|rs\.?\s*)([\d,]+)|([\d,]+)\s*(?:rupees|inr)/i),amount=amt?Number((amt[1]||amt[2]).replace(/,/g,'')):0,free=84620-38400-12000;if(!amount)return {text:`I can check a purchase against your sample monthly savings goal, bills and event reserve. Your plan has about ${money(free)} left after those commitments. Tell me the item and expected price—or paste its link in Spend gatekeeper to compare sample payment offers.`,route:'spend',routeLabel:'Check a purchase'};const after=free-amount,ok=after>=0;return {text:`Based on the sample numbers, ${ok?'this looks within your plan':'this would go beyond the amount left after bills and your event reserve'}: ${money(84620)} available, less ${money(38400)} in known bills and ${money(12000)} reserved for Diwali, leaves ${money(free)}. A ${money(amount)} purchase would leave about ${money(after)}. Your savings target is met. ${ok?'For a better checkout price, compare card rewards and any live merchant offer before paying.':''} This is guidance from mock data, not a payment approval.`,route:'spend',routeLabel:'Review in Spend gatekeeper',prefillAmount:amount,prefillName:(q.match(/(?:buy|buying|purchase|spend on)\s+(?:a |an )?([a-z0-9 -]+)/i)?.[1]||'Planned purchase').trim()}}if(/what.*(car|phone|asset).*worth|resale|deprecat|sell my (car|phone|gadget)/.test(q))return {text:'Your sample Hyundai Creta SX (2022) estimate is ₹13.2L, with an illustrative range of ₹12.6L–₹13.8L. The sample iPhone 15 Pro estimate is ₹72,000, range ₹65,000–₹78,000. These aren’t live marketplace quotes; variant, condition, mileage and location can change the value.',route:'assetpulse',routeLabel:'Open Asset Pulse'};if(/remind|reminder|set aside|save for|create.*goal/.test(q))return {text:'I can help prepare that as a goal or reminder. Share the target amount and date, and I’ll show you a review step before adding it to the sample plan. I won’t move funds or contact a bank.',route:'goals',routeLabel:'Open goals & events'};if(/what should|what next|attention|today|this week/.test(q))return {text:'Three things stand out in your sample money view: 1,850 card points expire in 36 days; Diwali is 44 days away with ₹12,000 still to plan; and ₹75,000 is above your current emergency-fund target. You could use points first, keep the event reserve intact, then review whether the extra cash should stay liquid.',route:'home',routeLabel:'Review your overview'};if(/idle cash|invest|where.*cash/.test(q))return {text:'Your sample emergency fund covers about 4.2 of a 6-month target. You also have ₹75,000 flagged as cash beyond that target. Keep the amount you need accessible; if you are considering the surplus, compare liquidity, risk and time horizon before choosing. I can show learning options, but I cannot verify current rates or recommend a specific product from this demo.',route:'invest',routeLabel:'Explore options'};if(/future|what if|goal|retire|house|home/.test(q))return {text:'I can sketch a future scenario from your sample goals and balances. Share the target amount and when you need it, and I’ll lay out a simple monthly saving estimate. Any result is illustrative, not a return forecast or investment recommendation.',route:'goals',routeLabel:'Open goals'};return {text:'I can answer questions about your sample balances, net worth, goals, bills, card benefits, credit score and purchase plans. What would you like to look at?'} }
function sendChat(text){const question=text.trim();if(!question||state.chatLoading)return;state.chatMessages.push({role:'user',text:question});state.chatLoading=true;render();setTimeout(()=>{const reply=agentReply(question);state.chatMessages.push({role:'assistant',...reply});state.chatLoading=false;render();document.getElementById('chatLog')?.scrollTo({top:99999,behavior:'smooth'})},420)}
function valuationFor(kind,paid,date,quote){if(quote>0)return {value:quote,source:'User entered quote · demo'};const rates={Car:.12,Phone:.25,Gadget:.22,Watch:.12,Property:0,Other:.15};const rate=rates[kind]??.15;const bought=new Date(`${date}-01T00:00:00`);const years=Math.max(0,(Date.now()-bought.getTime())/(365.25*86400000));return {value:Math.round(paid*Math.pow(1-rate,years)),source:kind==='Property'?'Needs local appraisal · sample value':'Illustrative category curve · not a live quote',rate}}
function saveAssetFromModal(){const name=document.getElementById('newAssetName'),kind=document.getElementById('newAssetKind'),paid=document.getElementById('newAssetPrice'),date=document.getElementById('newAssetDate'),quote=document.getElementById('newAssetQuote'),err=document.getElementById('assetFormError');const price=Number(paid?.value);if(!name?.value.trim()||!price||price<=0){err.textContent='Add the item name and purchase price to continue.';return}const estimate=valuationFor(kind.value,price,date.value,Number(quote.value));const loanBalance=Math.max(0,Number(document.getElementById('newAssetLoan').value)||0);const margin=kind.value==='Property' ? 0.05 : 0.08;state.trackedAssets.unshift({id:Date.now(),name:name.value.trim(),kind:kind.value,purchased:date.value,purchasePrice:price,value:estimate.value,loanBalance,rate:estimate.rate??null,range:[Math.round(estimate.value*(1-margin)),Math.round(estimate.value*(1+margin))],source:estimate.source});hideModal();if(state.view==='assetpulse')render();toast('Added to your sample Asset Pulse')}
function assetForm(optional=false,presetName='',presetPrice=''){const today=new Date().toISOString().slice(0,10);const kind=/car|auto|vehicle/i.test(presetName)?'Car':/phone|iphone|android/i.test(presetName)?'Phone':/watch/i.test(presetName)?'Watch':'Gadget';showModal(optional?'Want to track an item you own?':'Add an asset',`<p>${optional?'You can add one now or skip and come back later. Everything here is sample data.':'Add a car, phone, gadget, watch or property. Add a market quote if you have one; otherwise we’ll show a clearly labeled illustrative estimate.'}</p><div class="field"><label for="newAssetKind">Type</label><select id="newAssetKind"><option ${kind==='Car'?'selected':''}>Car</option><option ${kind==='Phone'?'selected':''}>Phone</option><option ${kind==='Gadget'?'selected':''}>Gadget</option><option ${kind==='Watch'?'selected':''}>Watch</option><option>Property</option><option>Other</option></select></div><div class="field" style="margin-top:11px"><label for="newAssetName">Make, model and variant</label><input id="newAssetName" placeholder="e.g. Hyundai Creta SX (O)" value="${escapeHtml(presetName)}"></div><div class="form-row"><div class="field"><label for="newAssetPrice">Purchase price</label><input id="newAssetPrice" type="number" min="1" placeholder="₹ 0" value="${escapeHtml(presetPrice)}"></div><div class="field"><label for="newAssetDate">Purchase date</label><input id="newAssetDate" type="month" value="${today.slice(0,7)}"></div></div><div class="form-row"><div class="field"><label for="newAssetQuote">Current resale / market quote <span class="optional">Optional</span></label><input id="newAssetQuote" type="number" min="0" placeholder="Leave blank for an illustrative estimate"></div><div class="field"><label for="newAssetLoan">Outstanding loan on this item <span class="optional">Optional</span></label><input id="newAssetLoan" type="number" min="0" placeholder="₹ 0"></div></div><p class="form-error" id="assetFormError" role="alert"></p><div class="asset-modal-actions">${optional?'<button class="btn" id="skipAsset">Skip for now</button>':''}<button class="btn primary" id="saveAsset">${optional?'Add and continue':'Save asset'}</button></div>`);document.getElementById('saveAsset').onclick=saveAssetFromModal;document.getElementById('skipAsset')?.addEventListener('click',()=>{hideModal();toast('You can add assets anytime from Asset Pulse')})}
const renderers={home:overview,chat,spend,divers,assetpulse:assetPulse,invest,rewards,protect,credit,loans,goals,accounts,profile};
function render(){try{const page=renderers[state.view];if(typeof page!=='function')throw new Error(`Unknown page: ${state.view}`);document.body.classList.remove('theme-student','theme-early','theme-established');document.body.classList.add(`theme-${state.segment||'early'}`);document.getElementById('pageCrumb').textContent=titles[state.view]||'Overview';root.innerHTML=page();document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.go)));document.querySelectorAll('[data-toast]').forEach(b=>b.addEventListener('click',()=>toast(b.dataset.toast)));bindPage()}catch(error){console.error('OptiSpend could not render this page:',error);root.innerHTML=`<div class="startup-card startup-error"><span class="startup-mark">!</span><h1>Your money view didn’t load</h1><p>Please refresh this page. If it stays blank, close this tab and reopen <strong>http://localhost:8000</strong>.</p><button class="btn primary" onclick="location.reload()">Refresh OptiSpend&nbsp; ↻</button></div>`}}
function navigate(view){state.view=view;document.getElementById('sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'})}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2500)}
function showModal(title,html){document.getElementById('modalContent').innerHTML=`<div class="eyebrow">OPTISPEND</div><h2 id="modalTitle">${title}</h2>${html}`;document.getElementById('modalBackdrop').hidden=false}
function hideModal(){document.getElementById('modalBackdrop').hidden=true}
function millenniaBenefits(){showModal('HDFC Millennia · full benefits',`<p class="benefit-intro">A concise guide to the card in this sample profile. Offers can change; confirm the issuer’s current terms before paying.</p><div class="benefit-detail"><strong>5% cashback · selected online merchants</strong><p>Amazon, BookMyShow, Cult.fit, Flipkart, Myntra, Sony LIV, Swiggy, Tata CLiQ, Uber and Zomato. Up to 1,000 CashPoints per cycle. Eligible non-EMI transactions only.</p></div><div class="benefit-detail"><strong>1% cashback · other eligible spends</strong><p>Separate cap of up to 1,000 CashPoints per cycle. Fuel, EMI, wallet, rent and government-related transactions are excluded. 1 CashPoint = ₹1 when redeemed against the card statement.</p></div><div class="benefit-detail"><strong>Quarterly spend milestone</strong><p>At ₹1 lakh eligible spend in a calendar quarter, choose one: a ₹1,000 brand voucher or one domestic airport lounge access voucher. These are alternatives; complimentary walk-in lounge visits have been discontinued.</p></div><div class="benefit-detail"><strong>Other issuer-listed benefits</strong><p>10% additional Swiggy Dineout discount (coupon and terms apply); 1% fuel surcharge waiver on ₹400–₹5,000 transactions, capped at ₹250 per statement cycle; 1,000 welcome CashPoints on paying the joining fee; renewal fee waiver on ₹1 lakh spend in the anniversary year.</p></div><div class="benefit-detail"><strong>Other useful benefits</strong><p>Up to 10% additional cashback via SmartBuy / PayZapp Shop on eligible offers; up to 50 days interest-free credit subject to merchant charge submission.</p></div><div class="benefit-detail"><strong>Fee & eligibility</strong><p>₹1,000 joining / annual fee plus applicable taxes; renewal fee may be waived after ₹1 lakh spend in the anniversary year. Issuer currently lists salaried Indian applicants age 21–40 with net monthly income above ₹35,000, or self-employed Indian applicants age 21–40 with ITR above ₹6 lakh/year. Issuer approval and current criteria apply.</p></div><p class="source-links">Issuer details · checked 26 Sep 2026: <a href="https://www.hdfc.bank.in/credit-cards/millennia-credit-card" target="_blank" rel="noopener">Card benefits</a> · <a href="https://www.hdfc.bank.in/content/dam/hdfcbankpws/in/en/personal-banking/discover-products/cards/credit-cards/millennia-credit-card/Terms-and-Conditions-Millennia-Credit-Card.pdf" target="_blank" rel="noopener">Cashback terms</a> · <a href="https://www.hdfc.bank.in/content/dam/hdfcbankpws/in/en/personal-banking/discover-products/cards/credit-cards/millennia-credit-card/pdf/lounge-voucher-on-millennia-credit-card.pdf" target="_blank" rel="noopener">Lounge voucher terms</a></p>`)}
function segmentModal(){showModal('Choose your life stage',`<p>We’ll tailor your home view and suggestions to what matters most right now.</p><div class="segment-grid"><button class="segment ${state.segment==='student'?'selected':''}" data-segment="student"><span class="seg-emoji">🎓</span><strong>College student</strong><small>Build confidence with spending, saving and first accounts.</small></button><button class="segment ${state.segment==='early'?'selected':''}" data-segment="early"><span class="seg-emoji">🌱</span><strong>Early career</strong><small>Set up strong habits while your income grows.</small></button><button class="segment ${state.segment==='established'?'selected':''}" data-segment="established"><span class="seg-emoji">✦</span><strong>Established / high earning</strong><small>See the whole picture and coordinate your money.</small></button></div><button class="btn primary" id="saveSegment">Save preferences&nbsp; →</button>`);document.querySelectorAll('[data-segment]').forEach(b=>b.onclick=()=>{state.segment=b.dataset.segment;document.querySelectorAll('[data-segment]').forEach(x=>x.classList.toggle('selected',x===b))});document.getElementById('saveSegment').onclick=()=>{localStorage.setItem('optiSegment',state.segment);hideModal();render();toast('Your home view is personalized')};}
